/**
 * Cargo.lock parsing unit tests (ADR 0063, Decision 2)
 */

import { describe, expect, it } from "vitest";
import { parseCargoLockContent } from "./cargo-lock-parse.js";

const REAL_SHAPE_LOCK = `
# This file is automatically @generated by Cargo.
# It is not intended for manual editing.
version = 3

[[package]]
name = "serde"
version = "1.0.219"
source = "registry+https://github.com/rust-lang/crates.io-index"
dependencies = [
 "serde_core",
]

[[package]]
name = "serde_core"
version = "1.0.219"
source = "registry+https://github.com/rust-lang/crates.io-index"

[[package]]
name = "local-tool"
version = "0.1.0"
dependencies = [
 "serde",
]
`;

describe("parseCargoLockContent", () => {
  it("extracts name → version for every [[package]] entry", () => {
    const result = parseCargoLockContent(REAL_SHAPE_LOCK);

    expect(result).not.toBeNull();
    expect(result?.format).toBe("Cargo.lock");
    expect(result?.resolvedVersions.get("serde")).toBe("1.0.219");
    expect(result?.resolvedVersions.get("serde_core")).toBe("1.0.219");
    expect(result?.resolvedVersions.get("local-tool")).toBe("0.1.0");
    expect(result?.warnings).toEqual([]);
  });

  it("records every package as a transitive candidate — the manifest diff is mergeManifestWithLock's job", () => {
    // Same division of labor as go.sum (ADR 0038): the lock file alone
    // cannot distinguish direct from transitive, so all names go into
    // transitivePackages and mergeManifestWithLock() skips any of them
    // the manifest itself declares.
    const result = parseCargoLockContent(REAL_SHAPE_LOCK);

    expect(result?.transitivePackages.has("serde")).toBe(true);
    expect(result?.transitivePackages.has("serde_core")).toBe(true);
    expect(result?.transitivePackages.has("local-tool")).toBe(true);
  });

  it("returns null for invalid TOML", () => {
    const result = parseCargoLockContent("this is not [valid toml\n===");

    expect(result).toBeNull();
  });

  it("treats a lock file with no [[package]] array as an empty lock", () => {
    const result = parseCargoLockContent("version = 4\n");

    expect(result).not.toBeNull();
    expect(result?.resolvedVersions.size).toBe(0);
    expect(result?.format).toBe("Cargo.lock");
  });

  it("skips non-table entries and entries missing name or version with warnings", () => {
    const lock = `
[[package]]
name = "serde"
version = "1.0.219"

[[package]]
name = "broken"
`;
    const result = parseCargoLockContent(lock);

    expect(result?.resolvedVersions.get("serde")).toBe("1.0.219");
    expect(result?.resolvedVersions.has("broken")).toBe(false);
    expect(result?.warnings.length).toBe(1);
  });

  it("keeps the first occurrence when the same name appears twice", () => {
    const lock = `
[[package]]
name = "dup"
version = "1.0.0"

[[package]]
name = "dup"
version = "2.0.0"
`;
    const result = parseCargoLockContent(lock);

    expect(result?.resolvedVersions.get("dup")).toBe("1.0.0");
    expect(result?.warnings.length).toBeGreaterThan(0);
  });
});
